// ListTaxonomySuggestionsParams defines parameters for ListTaxonomySuggestions.
type ListTaxonomySuggestionsParams struct {
	// Tier held: proposals waiting on an admin.
	Tier        *string `form:"tier,omitempty" json:"tier,omitempty"`
	Page        *int    `form:"page,omitempty" json:"page,omitempty"`
	PerPage     *int    `form:"per_page,omitempty" json:"per_page,omitempty"`
	Q           *string `form:"q,omitempty" json:"q,omitempty"`
	TargetTagId *int    `form:"target_tag_id,omitempty" json:"target_tag_id,omitempty"`

	// SortBy Field to sort by. score (sum of votes), votes (unique voter count), comment_count, last_comment_at, created_at.
	SortBy *string `form:"sort_by,omitempty" json:"sort_by,omitempty"`

	// Sort Sort direction. Pairs with sort_by.
	Sort *string `form:"sort,omitempty" json:"sort,omitempty"`

	// Action Comma-separated subset of create,rename,merge,describe,link. Defaults to all.
	Action *string `form:"action,omitempty" json:"action,omitempty"`

	// Discussion Filter by comment presence: 'with' = has at least one comment, 'without' = none. Omit for any.
	Discussion *string `form:"discussion,omitempty" json:"discussion,omitempty"`

	// Edited Filter by edit status: 'yes' = edited, 'no' = never edited. Omit for any.
	Edited *string `form:"edited,omitempty" json:"edited,omitempty"`

	// Review Filter by review state: unreviewed, reviewed, approved (has approvals), rejected (has rejections). Omit for any.
	Review *string `form:"review,omitempty" json:"review,omitempty"`

	// Held Filter by hold: 'yes' = held for an admin, 'no' = not held. Omit for any.
	Held *string `form:"held,omitempty" json:"held,omitempty"`

	// TagType Filter by tag type: the proposed type on a create, otherwise the target tag's type. Omit for any.
	TagType *string `form:"tag_type,omitempty" json:"tag_type,omitempty"`

	// Examples Filter by example galleries: 'with' = has at least one, 'without' = none. Omit for any.
	Examples *string `form:"examples,omitempty" json:"examples,omitempty"`
}

